/* Marketing revision: supplied artwork, brand destinations and company story. */
const R=window.REVISION_ASSETS;
const rasset=key=>R[key]||'';
const brandArt={Archer:'1.1 Archer.png',Classic:'1.2 classic.png',Biosilk:'1.3 Biosilk.png',Supremo:'1.4 Supremo.png'};
const brandBanner={Archer:'2.1 banner de archer.png',Classic:'2.2 banner de classic.png',Biosilk:'2.3 banner de biosilk.png',Supremo:'2.4 banner de supremo.png'};
const brandUrl=name=>'#marca?nombre='+encodeURIComponent(name);
const heroArts=['1 Archer.png','1.2 Classic.png','1.3 Biosilk.png','1.4 Supremo.png'];
let homeIndex=0,homeTimer,homePaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const categoryInfo={hogar:{title:'Un hogar que se siente bien.',text:'Soluciones para la cocina, la ropa y cada rincón de tu casa.',image:'Cuidado del Hogar.png'},personal:{title:'Tu cuidado, todos los días.',text:'Encuentra tu rutina, desde el cabello hasta el cuidado de la piel.',image:'Cuidado Personal.png'},institucional:{title:'Limpieza a la altura de tu equipo.',text:'Presentaciones de 5 litros y atención para empresas e instituciones.',image:'Institucional.png'}};
function benefitStrip(){return `<div class="shell revision-benefits">${[['1.1 Fabricacion Boliviana 2.png','Fabricación boliviana','De nuestra fábrica a tu día a día'],['1.2 El formato que necesitas.png','El formato que necesitas','Elige entre nuestras presentaciones'],['1.3 Atencion por whatsApp.png','Atención por WhatsApp','Te acompañamos en tu pedido']].map(([im,t,d])=>`<div><img src="${rasset('1 Iconos/'+im)}" alt=""><span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div>`}
function categoryCards(names=['hogar','personal','institucional'],brand=''){return `<div class="revision-categories">${names.map(key=>{const c=categoryInfo[key],categoryImage=brand==='Classic'&&key==='institucional'?rasset('3 Cada marca un mundo/2.2 banner de classic.png'):rasset('2 Un Cuidado para todo/'+c.image),to=key==='institucional'&&!brand?'#institucional':'#tienda?categoria='+key+(brand?'&marca='+brand:'');return `<a class="revision-category" href="${to}"><img src="${categoryImage}" alt="${key==='hogar'?'Productos para el hogar':key==='personal'?'Productos de cuidado personal':'Productos institucionales'}" loading="lazy"><div><span>${key==='hogar'?'CUIDADO DEL HOGAR':key==='personal'?'CUIDADO PERSONAL':'LIMPIEZA INSTITUCIONAL'}</span><p>${c.text}</p><b>Ver productos <span aria-hidden="true">↗</span></b></div></a>`}).join('')}</div>`}
home=function(){return `<section class="home-slideshow" aria-roledescription="carrusel" aria-label="Archer, Classic, Biosilk y Supremo"><h1 class="sr-only">Limpieza y cuidado para cada día</h1><div id="home-slide"></div><div class="home-slide-controls"><button data-home-prev aria-label="Imagen anterior">←</button><div>${brands.map((b,i)=>`<button data-home-index="${i}" aria-label="Ver portada de ${b.name}">${b.name}</button>`).join('')}</div><button data-home-next aria-label="Siguiente imagen">→</button><button data-home-pause aria-label="${homePaused?'Reanudar':'Pausar'} portada">${homePaused?'▶':'Ⅱ'}</button></div></section>${benefitStrip()}<section class="section shell"><div class="section-heading"><div><span class="eyebrow">PARA CADA PARTE DE TU DÍA</span><h2>Un cuidado para todo.</h2></div><a class="text-link" href="#tienda">Explorar productos ↗</a></div>${categoryCards()}</section><section class="revision-promo shell"><div class="section-heading"><div><span class="eyebrow">TUS FAVORITOS, MÁS CERCA</span><h2>Promociones.</h2></div><a href="#tienda" class="text-link">Explorar la tienda ↗</a></div><a href="#tienda" class="editorial-promo"><div><span class="eyebrow">DE NUESTRA FÁBRICA A TU HOGAR</span><h3>Compra directo.<br>Cuida más.</h3><p>Reúne tus favoritos, elige su presentación y prepara tu pedido en un solo lugar.</p><span class="button white">Elegir mis productos ↗</span></div><img src="${rasset('Compra directo, Cuida más.jpg')}" alt="Productos Archer para la limpieza de tu hogar" loading="lazy"></a></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">UNA FAMILIA DE MARCAS</span><h2>Cada marca, un mundo.</h2></div></div>${brandCards()}</section>`};
function showHome(index){const target=document.getElementById('home-slide');if(!target)return;homeIndex=(index+4)%4;const b=brands[homeIndex];target.innerHTML=`<a href="#tienda?marca=${b.name}" class="home-full-art"><img src="${asset('Propuestas web/Inicio/'+heroArts[homeIndex])}" alt="${b.name}: ${b.title.replace('\n',' ')} Explorar productos." fetchpriority="high"></a><div class="mobile-hero-cta"><span>${b.name} · ${b.text}</span><a class="button" href="${brandUrl(b.name)}">Descubrir ${b.name} ↗</a></div>`;document.querySelectorAll('[data-home-index]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.homeIndex)===homeIndex));setHeaderBrand(b.name)}
function runHome(){clearInterval(homeTimer);if(!homePaused)homeTimer=setInterval(()=>{if(!document.hidden&&!productDialog.open&&!cartDialog.open)showHome(homeIndex+1)},5500)}
function setHeaderBrand(name='Archer'){const logo=document.querySelector('.header .logo');logo.querySelector('img').src=brandLogo(name);logo.querySelector('img').alt=name;logo.setAttribute('aria-label',name+', inicio');}
function brandCards(){return `<div class="brand-art-grid revision-brand-cards">${brands.map(b=>`<a href="${brandUrl(b.name)}"><img src="${rasset('3 Cada marca un mundo/'+brandArt[b.name])}" alt="Descubre ${b.name}" loading="lazy"><span><b>${b.name}</b> Descubrir la marca ↗</span></a>`).join('')}</div>`}
brandsPage=function(){return `<section class="brands-title shell"><span class="eyebrow">CUATRO MARCAS. UN MISMO COMPROMISO.</span><h1>Encuentra tu <em>favorita.</em></h1><p>Una solución para tu hogar. Un cuidado para ti.</p></section><section class="brand-experience" aria-roledescription="carrusel" aria-label="Nuestras marcas"><div id="brand-stage"></div><div class="brand-progress" aria-hidden="true"><span></span></div><div class="brand-controls shell"><button class="circle-control" data-brand-prev aria-label="Marca anterior">←</button><div class="brand-tabs">${brands.map((b,i)=>`<button data-brand-index="${i}" aria-label="Ver marca ${b.name}"><img src="${brandLogo(b.name)}" alt="${b.name}"></button>`).join('')}</div><button class="circle-control" data-brand-next aria-label="Siguiente marca">→</button><button class="circle-control" id="brand-pause" aria-label="${paused?'Reanudar':'Pausar'} animación">${paused?'▶':'Ⅱ'}</button></div></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">EXPLORA A TU MANERA</span><h2>Cada marca, un mundo.</h2></div></div>${brandCards()}</section>`};
showBrand=function(index){brandIndex=(index+brands.length)%brands.length;const b=brands[brandIndex],stage=document.getElementById('brand-stage');if(!stage)return;stage.innerHTML=`<div class="revision-brand-slide"><div class="shell revision-brand-scene"><div><img class="scene-logo" src="${brandLogo(b.name)}" alt="${b.name}"><h2>${b.title.replace('\n','<br>')}</h2><p>${b.text}</p><a class="button navy" href="${brandUrl(b.name)}">Descubrir ${b.name} ↗</a></div><button class="revision-brand-visual" data-brand-next aria-label="Ver siguiente marca"><img src="${rasset('3 Cada marca un mundo/'+brandArt[b.name])}" alt="Productos ${b.name}"><span>Siguiente marca →</span></button></div></div>`;document.querySelectorAll('[data-brand-index]').forEach(el=>{const current=Number(el.dataset.brandIndex)===brandIndex;el.classList.toggle('active',current);el.setAttribute('aria-pressed',current)});document.querySelector('.brand-experience').classList.toggle('paused',paused)};
function brandLanding(params){const name=brands.some(b=>b.name===params.get('nombre'))?params.get('nombre'):'Archer',b=brands.find(b=>b.name===name),items=C.filter(p=>p.brand===name);return `<div class="brand-landing brand-${name.toLowerCase()}"><div class="shell brand-local-nav"><img src="${brandLogo(name)}" alt="${name}"><span>${b.text}</span><a href="#productos">Todas las marcas ↗</a></div><section class="brand-landing-hero"><div class="shell"><div><span class="eyebrow">${name==='Archer'?'UN HOGAR MÁS LIMPIO':'CUIDADO QUE TE ACOMPAÑA'}</span><h1>${b.title.replace('\n','<br>')}</h1><p>${b.text}</p><a class="button" href="#tienda?marca=${name}">Comprar ${name} ↗</a></div><img src="${rasset('3 Cada marca un mundo/'+brandArt[name])}" alt="La familia de productos ${name}"></div></section>${benefitStrip()}<section class="section shell"><div class="section-heading"><div><span class="eyebrow">ENCUENTRA TU RUTINA</span><h2>Compra por categoría.</h2></div></div>${name==='Archer'?categoryCards(['hogar','institucional'],name):name==='Classic'?`<div class="routine-categories">${[['Shampoos.png','Shampoos','shampoo'],['acondicionadores.png','Acondicionadores','acondicionador']].map(([im,t,q])=>`<a href="#tienda?marca=${name}&buscar=${q}"><img src="${rasset(im)}" alt="${t} Classic"><h3>${t}</h3><span>Elegir mi presentación ↗</span></a>`).join('')}</div>${categoryCards(['personal','institucional'],name)}`:`<div class="routine-categories">${[['Shampoo','shampoo'],['Acondicionador','acondicionador']].map(([t,q])=>{const p=items.find(p=>p.name.toLowerCase().includes(q))||items[0];return `<a href="#tienda?marca=${name}&buscar=${q}"><img src="${p.image}" alt="${t} ${name}"><h3>${t}</h3><span>Ver presentaciones ↗</span></a>`}).join('')}</div>`}</section><section class="shell brand-wide-banner"><img src="${rasset('3 Cada marca un mundo/'+brandBanner[name])}" alt="${name}, productos para tu día a día" loading="lazy"><div><h2>${name==='Archer'?'Que la limpieza sea más simple.':'Un cuidado que se siente.'}</h2><a href="#tienda?marca=${name}" class="button navy">Ver todos los productos ↗</a></div></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">DESCUBRE ${name.toUpperCase()}</span><h2>Productos destacados.</h2></div><a class="text-link" href="#tienda?marca=${name}">Ver todos ↗</a></div><div class="product-grid">${items.slice(0,4).map(p=>card(p)).join('')}</div></section></div>`}
const previousShop=shop;
shop=function(params){let html=previousShop(params);const cat=params.get('categoria'),brand=params.get('marca'),c=categoryInfo[cat];const title=c?.title||(brand&&brand!=='todas'?'Tu selección '+esc(brand)+'.':'El cuidado que buscas, en un solo lugar.'),text=c?.text||'Descubre nuestras marcas, elige tu presentación y prepara tu pedido.',im=c?rasset('2 Un Cuidado para todo/'+c.image):brandArt[brand]?rasset('3 Cada marca un mundo/'+brandArt[brand]):rasset('Compra directo, Cuida más.jpg');return html.replace(/<section class="shop-heading">[\s\S]*?<section class="shell shop-section">/,`<section class="revision-shop-hero"><div class="shell"><div><div class="breadcrumb"><a href="#inicio">Inicio</a><span>/</span>Tienda</div><span class="eyebrow">${c?esc(cat==='hogar'?'CUIDADO DEL HOGAR':cat==='personal'?'CUIDADO PERSONAL':'LIMPIEZA INSTITUCIONAL'):'COMPRA DIRECTO'}</span><h1>${title}</h1><p>${text}</p></div><img src="${im}" alt="${c?'Productos de la categoría seleccionada':'Productos de nuestras marcas'}"></div></section><section class="shell shop-section">`)};
faqs.splice(0,faqs.length,
 ['¿Cómo compro en la tienda?','Elige tus productos, selecciona sus presentaciones y agrégalos al carrito. Continúa con tu pedido, ingresa los datos de contacto, entrega y factura, y revisa el detalle. Al enviarlo por WhatsApp, nuestro equipo confirmará disponibilidad, entrega y forma de pago.'],
 ['¿Cómo se calcula el precio de la tienda?','Los precios se muestran en bolivianos (Bs), por presentación, y ya incluyen impuestos. No se añade ningún recargo por facturación. El carrito muestra el subtotal y el total de los productos seleccionados. Si corresponde un costo de envío, nuestro equipo lo confirma antes del pago. Para compras por volumen, solicita una propuesta comercial.'],
 ['¿El envío es gratuito?','Las condiciones de entrega dependen de tu ubicación y del pedido. Consulta con nuestro equipo el costo, la cobertura y la fecha de entrega antes de pagar. El envío no se calcula automáticamente en esta página.'],
 ['¿Puedo solicitar factura?','Sí. Todas las ventas se facturan. Al preparar el pedido, ingresa tu NIT o CI y tu nombre o razón social. Si necesitas corregir estos datos, comunícate con el equipo al 77226763 antes de finalizar la compra.'],
 ['¿Tienen presentaciones para empresas?','Sí. Contamos con presentaciones de 5 litros y atención personalizada para empresas, instituciones y procesos de compra. Selecciona “Hablar con el equipo” para consultar productos, volúmenes, fichas técnicas y condiciones comerciales.'],
 ['¿Puedo pagar dentro de la página?','Por el momento, no se realizan cobros dentro de esta página. Puedes preparar tu pedido y enviarlo por WhatsApp; el equipo comercial te indicará los medios de pago disponibles. No ingreses datos de tarjetas en los campos del pedido.']);
function faqSection(){return `<section class="faq-section"><div class="shell faq-grid"><div><span class="eyebrow">ESTAMOS PARA AYUDARTE</span><h2>Preguntas<br>frecuentes.</h2><p>Tu compra, paso a paso. Resuelve tus dudas antes de preparar tu pedido.</p><a href="${wa('Hola, tengo una consulta sobre los productos de Archer.')}" target="_blank" rel="noopener" class="button navy">Hablar con el equipo ↗</a></div><div>${faqs.map(([q,a],i)=>`<details class="faq"><summary><span class="faq-number">0${i+1}</span>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></div></section>`}
about=function(){return `<section class="revision-about shell"><div><span class="eyebrow">MULTI INTERNACIONAL S.R.L. · BOLIVIA</span><h1>Hechos aquí.<br>Para cuidar<br><em>lo que importa.</em></h1><p>Somos una empresa boliviana dedicada a la fabricación y comercialización de productos de limpieza para el hogar y de cuidado personal.</p><a class="button navy" href="#historia" data-scroll-request>Conoce nuestra historia ↓</a></div><figure><img src="${asset('Propuestas web/Nosotros/Foto empresa.png')}" alt="Instalaciones de Multi Internacional"><figcaption>El lugar donde comienza el cuidado de cada día.</figcaption></figure></section><section class="revision-values"><div class="shell values-grid">${[['2.1 Cuidar el bienestar de cada familia.png','NUESTRA MISIÓN','Cuidar el bienestar de cada familia.','Fabricar productos de limpieza e higiene personal de alta calidad, que brinden soluciones efectivas y seguras para los hogares bolivianos, contribuyendo al bienestar familiar.'],['2.2 Crecer con calidad e innovación.png','NUESTRA VISIÓN','Crecer con calidad e innovación.','Ser la empresa líder en Bolivia en la fabricación de productos de limpieza y cuidado personal, destacando por nuestra innovación continua, calidad superior y compromiso con el cliente y el medio ambiente.']].map(([im,e,t,p])=>`<article><img src="${rasset('1 Iconos/'+im)}" alt=""><span class="eyebrow">${e}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</div></section><section class="section shell history-section" id="historia"><div class="history-intro"><span class="eyebrow">NUESTRA HISTORIA</span><h2>Crecemos contigo.</h2><p>Desde nuestros inicios, trabajamos con una visión clara: llevar productos de calidad a más hogares. Con esfuerzo, integridad y un equipo comprometido, seguimos construyendo nuestra historia.</p></div><div class="history-timeline">${[['1993','Nuestros inicios','El inicio de una historia dedicada a la limpieza y al cuidado.'],['2007','Una nueva etapa','Continuamos desarrollando nuestras capacidades y nuestra familia de productos.'],['Hoy','Seguimos creciendo','Nuestras marcas acompañan el cuidado de hogares, familias y empresas.']].map(([year,t,p])=>`<article><span class="history-dot"></span><strong>${year}</strong><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="section shell company-section"><div class="section-heading"><div><span class="eyebrow">DETRÁS DE CADA PRODUCTO</span><h2>El lugar donde todo comienza.</h2></div></div><div class="company-gallery">${[1,2,3].map(n=>`<figure><img src="${asset('Propuestas web/Nosotros/Foto empresa '+n+'.png')}" alt="Instalaciones y almacenes de Multi Internacional, vista ${n}" loading="lazy"></figure>`).join('')}</div></section>${faqSection()}`};
const priorInstitutional=institutional;
institutional=function(){return priorInstitutional().replace(/<div class="institution-packs">[\s\S]*?<\/div><\/div><\/section>/,`<div class="revision-institution-art"><img src="${rasset('2 Un Cuidado para todo/Institucional.png')}" alt="Productos Archer en formato institucional"><span>FORMATO 5 L · ATENCIÓN A EMPRESAS</span></div></div></section>`)};
const priorRoute=route;
route=function(){clearInterval(homeTimer);const [page,query]=(location.hash.slice(1)||'inicio').split('?');if(page==='historia'){document.getElementById('historia')?.scrollIntoView({behavior:'smooth'});return}if(page==='marca'){clearInterval(carouselTimer);productDialog.close();cartDialog.close();document.getElementById('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');main.innerHTML=brandLanding(new URLSearchParams(query));const name=new URLSearchParams(query).get('nombre');setHeaderBrand(brandFiles[name]?name:'Archer');document.title=(brandFiles[name]?name:'Archer')+' | Productos y cuidado';document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.hash==='#productos'));window.scrollTo(0,0);saveCart();return}priorRoute();setHeaderBrand('Archer');if(page==='inicio'){showHome(homeIndex);runHome()}if(page==='tienda'){const params=new URLSearchParams(query),search=params.get('buscar');if(search){document.getElementById('search').value=search;filterShop()}if(brandFiles[params.get('marca')])setHeaderBrand(params.get('marca'))}};
window.removeEventListener('hashchange',priorRoute);window.addEventListener('hashchange',route);
document.addEventListener('click',e=>{const b=e.target.closest('[data-home-index]');if(b){showHome(Number(b.dataset.homeIndex));runHome()}if(e.target.closest('[data-home-prev]')){showHome(homeIndex-1);runHome()}if(e.target.closest('[data-home-next]')){showHome(homeIndex+1);runHome()}const pause=e.target.closest('[data-home-pause]');if(pause){homePaused=!homePaused;pause.textContent=homePaused?'▶':'Ⅱ';pause.setAttribute('aria-label',homePaused?'Reanudar portada':'Pausar portada');runHome()}});
document.querySelector('.footer').innerHTML=`<div class="shell footer-invitation"><div><span class="eyebrow">ESTAMOS CERCA</span><h2>Un hogar más limpio.<br>Un cuidado para todos.</h2></div><a class="button white" href="${wa('Hola, quisiera información sobre los productos de Archer.')}" target="_blank" rel="noopener">Conversemos por WhatsApp ↗</a></div><div class="footer-top"><div class="footer-family"><h3>Nuestras marcas</h3><div>${brands.map(b=>`<a href="${brandUrl(b.name)}"><img src="${brandLogo(b.name)}" alt="${b.name}"></a>`).join('')}</div><p>Multi Internacional S.R.L.<br>Limpieza y cuidado personal, hechos en Bolivia.</p></div><div><h3>Descubre</h3><a href="#tienda?categoria=hogar">Cuidado del hogar</a><a href="#tienda?categoria=personal">Cuidado personal</a><a href="#institucional">Limpieza institucional</a><a href="#tienda">Tienda online</a></div><div><h3>Estamos cerca</h3><a href="#nosotros">Nuestra empresa e historia</a><a href="#internacionales">Negocios internacionales</a><a href="mailto:ventas@archer.com.bo">ventas@archer.com.bo</a><a href="https://wa.me/59177226763" target="_blank" rel="noopener">WhatsApp · 77226763</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Multi Internacional S.R.L. · Bolivia</span><div><a href="https://www.facebook.com/ArcherLimpieza" target="_blank" rel="noopener">Facebook</a><a href="https://www.instagram.com/archer_limpieza" target="_blank" rel="noopener">Instagram</a><a href="https://www.tiktok.com/@archer_limpieza" target="_blank" rel="noopener">TikTok</a></div></div>`;
route();
